   const page=Number(key),notListed=!item.primary,orphan=core.has(item.section)&&item.owners.length>0&&!item.owners.some(id=>retained.has(id));
   if(notListed||orphan){excluded.push({page,reason:notListed?'outside the two approved textbook vocabulary sources':'owning exercise not selected',owners:item.owners});window.SCHOOL_EXCLUDED_PAGES.add(page);continue;}
   active.push(page);
   if(item.primarySource?.title.startsWith('教材 GLOSSARY')){const p=L.pages[page-1];p.html=p.html.replaceAll('UNDERSTANDING KEY VOCABULARY','GLOSSARY');if(item.title)item.title=item.title.replaceAll('UNDERSTANDING KEY VOCABULARY','GLOSSARY');}
